2.快速排序如果你不满足我C语言基础计算技巧的排序方法 qsort那么以下介绍快排
原理：快速排序只有两个步骤：选一个基准值 pivot；把数组划分成两部分：左边全 ≤ pivot，右边全 ≥ pivot。划分完成后，pivot 就落在了它最终该在的位置上。接着对左右两段递归做同样的事，整个数组就有序了。partition 这个函数尤为重要分区写得好不好，直接决定了快排是 O(n log n) 还是 O(n²)。
第一版：Lomuto 分区法
用一个指针 i 维护”已确认小于 pivot”的区域边界：
static void swap(int *a, int *b) {    int t &#x3D; *a; *a &#x3D; *b; *b &#x3D; t;} &#x2F;&#x2F;交换函数
&#x2F;* 返回 pivot 最终所在的下标 &#x2F;int partition_lomuto(int a, int lo, int hi) {     &#x2F;&#x2F;a 是数组，lo 是这段的左边界，hi 是右边界    int pivot &#x3D; a[hi];      &#x2F; 取最后一个元素作基准 &#x2F;    int i &#x3D; lo;  &#x2F; i 指向”比标杆小的区域”的下一个空位&#x2F;    for (int j &#x3D; lo; j &lt; hi; ++j) {        if (a[j] &lt; pivot) {            swap(&amp;a[i], &amp;a[j]);            ++i;        }    }    swap(&amp;a[i], &amp;a[hi]);    &#x2F;* pivot 归位 *&#x2F;    return i;}
void quick_sort_lomuto(int *a, int lo, int hi) {    if (lo &gt;&#x3D; hi)	    return;    int p &#x3D; partition_lomuto(a, lo, hi);    quick_sort_lomuto(a, lo, p - 1);    quick_sort_lomuto(a, p + 1, hi);}优点：逻辑清晰，边界好记，pivot 位置一目了然。缺点：对已经有序的数组会退化成 O(n²)。因为每次都取末尾元素当基准，有序数组里它永远是最大值，分区后一边是 n-1 个元素、一边是 0 个，递归深度变成 O(n)。对大量重复元素同样退化。交换次数偏多。
第二版：Hoare 分区法
Hoare 是快排发明者本人给出的分区方案：两个指针从两端向中间夹逼（我第一次听说这个词还是在《机器学习的数学基础》里），各自找到”站错队”的元素再交换。
int partition_hoare(int *a, int lo, int hi) {    int pivot &#x3D; a[lo + (hi - lo) &#x2F; 2];    int i &#x3D; lo - 1, j &#x3D; hi + 1;    for (;;) {        do { ++i; } while (a[i] &lt; pivot);        do { –j; } while (a[j] &gt; pivot);        if (i &gt;&#x3D; j) return j;        swap(&amp;a[i], &amp;a[j]);    }}
Hoare 版的分区交换次数大约只有 Lomuto 的三分之一，而且在元素全部相同时也能把数组对半分，不会退化。但是：返回的 j 不一定是 pivot 的最终位置，递归边界要写成 (lo, j) 和 (j+1, hi)，容易写错。注意：a[i] &lt; pivot 而不是 &lt;&#x3D;，a[j] &gt; pivot 而不是 &gt;&#x3D;，这两个不等号如果写反，遇到重复元素就会死循环。
优化继续第三版，短数组排序改用插入排序当子数组长度小于某个阈值（一般 8~32）时，快排的递归开销（函数调用、栈帧）已经超过了排序本身。此时插入排序虽然理论复杂度是 O(n²)，但常数极小、缓存友好，反而更快。
#define INSERTION_THRESHOLD 16
static void insertion_sort(int *a, int lo, int hi) {    for (int i &#x3D; lo + 1; i &lt;&#x3D; hi; ++i) {        int key &#x3D; a[i];        int j &#x3D; i - 1;        while (j &gt;&#x3D; lo &amp;&amp; a[j] &gt; key) {            a[j + 1] &#x3D; a[j];            –j;        }        a[j + 1] &#x3D; key;    }}
第四版三数取中选 pivot为了避免有序数组排序时间长我们从 a[lo]、a[mid]、a[hi] 里取中位数当基准：
static int median_of_three(int a, int lo, int hi) {    int mid &#x3D; lo + ((hi - lo) &gt;&gt; 1);    if (a[mid] &lt; a[lo]) swap(&amp;a[mid], &amp;a[lo]);    if (a[hi]  &lt; a[lo]) swap(&amp;a[hi],  &amp;a[lo]);    if (a[hi]  &lt; a[mid]) swap(&amp;a[hi], &amp;a[mid]);    &#x2F; 此时 a[lo] &lt;&#x3D; a[mid] &lt;&#x3D; a[hi] &#x2F;    swap(&amp;a[mid], &amp;a[lo]);   &#x2F; 把中位数换到 lo 位置 *&#x2F;    return a[lo];}
优点:a[hi] 一定 ≥ pivot，所以从左往右扫描不会越界；a[lo] 就是 pivot，所以从右往左扫描也不会越界。内层循环因此可以省掉边界判断(十分方便)
第五版尾递归消除和优先递归小分区
快排的递归深度最坏是 O(n)，造成栈溢出，如何解决？优先递归较短的那一半，较长的那一半用循环处理（尾递归消除）。这样栈深度最坏也是 O(log n)小区间直接插排返回，不再递归。
void quick_sort(int a, int lo, int hi) {    while (lo &lt; hi) {        if (hi - lo &lt; INSERTION_THRESHOLD) {            insertion_sort(a, lo, hi);            return;        }        int p &#x3D; partition(a, lo, hi);        if (p - lo &lt; hi - p) {          &#x2F; 左边更短 &#x2F;            quick_sort(a, lo, p - 1);   &#x2F; 递归处理短的 &#x2F;            lo &#x3D; p + 1;                 &#x2F; 长的走循环 *&#x2F;        } else {            quick_sort(a, p + 1, hi);            hi &#x3D; p - 1;        }    }}
最终（终于到这一步了，直接超级拼装）
#include &lt;stdio.h&gt;#include &lt;stdlib.h&gt;#include &lt;string.h&gt;#include &lt;time.h&gt;
#define INSERTION_THRESHOLD 16
static inline void swap(int *a, int *b) {    int t &#x3D; *a; *a &#x3D; *b; *b &#x3D; t;}
static void insertion_sort(int *a, int lo, int hi) {    for (int i &#x3D; lo + 1; i &lt;&#x3D; hi; ++i) {        int key &#x3D; a[i];        int j &#x3D; i - 1;        while (j &gt;&#x3D; lo &amp;&amp; a[j] &gt; key) {            a[j + 1] &#x3D; a[j];            –j;        }        a[j + 1] &#x3D; key;    }}
&#x2F;* 三数取中，并把中位数放到 a[lo]，返回其值 *&#x2F;static int median_of_three(int *a, int lo, int hi) {    int mid &#x3D; lo + ((hi - lo) &gt;&gt; 1);    if (a[mid] &lt; a[lo]) swap(&amp;a[mid], &amp;a[lo]);    if (a[hi]  &lt; a[lo]) swap(&amp;a[hi],  &amp;a[lo]);    if (a[hi]  &lt; a[mid]) swap(&amp;a[hi], &amp;a[mid]);    swap(&amp;a[mid], &amp;a[lo]);    return a[lo];}
&#x2F;* Hoare 分区；返回分界点 j，a[lo..j] &lt;&#x3D; pivot &lt;&#x3D; a[j+1..hi] &#x2F;static int partition(int a, int lo, int hi) {    int pivot &#x3D; median_of_three(a, lo, hi);    int i &#x3D; lo, j &#x3D; hi + 1;    for (;;) {        while (a[++i] &lt; pivot) { }   &#x2F;* a[hi] &gt;&#x3D; pivot        while (a[–j] &gt; pivot) { }   &#x2F; a[lo] &#x3D;&#x3D; pivot        if (i &gt;&#x3D; j) break;        swap(&amp;a[i], &amp;a[j]);    }    swap(&amp;a[lo], &amp;a[j]);             &#x2F; pivot 归位到 j *&#x2F;    return j;}
void quick_sort(int *a, int lo, int hi) {    while (lo &lt; hi) {        if (hi - lo &lt; INSERTION_THRESHOLD) {            insertion_sort(a, lo, hi);            return;        }        int p &#x3D; partition(a, lo, hi);        if (p - lo &lt; hi - p) {            quick_sort(a, lo, p - 1);            lo &#x3D; p + 1;        } else {            quick_sort(a, p + 1, hi);            hi &#x3D; p - 1;        }    }}
void quick_sort_array(int *a, size_t n) {    if (n &gt; 1) quick_sort(a, 0, (int)n - 1);}
